package main

const demoHTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Storage Lab</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#172334;font:14px system-ui,sans-serif}header{background:#fff;border-bottom:1px solid #dde3e9;padding:20px max(24px,calc((100vw - 1120px)/2));display:flex;justify-content:space-between;align-items:center}h1{font-size:24px;margin:0}h2{font-size:16px;margin:0 0 16px}p{color:#657487;line-height:1.5}main{max-width:1168px;margin:0 auto;padding:28px 24px}section{background:white;border:1px solid #dde3e9;border-radius:12px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px}.nodes{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;position:relative;padding:20px 0}.node{border:1px solid #d6e0e8;border-radius:10px;padding:16px;background:#f8fafc;position:relative;min-width:0}.node.active{animation:flash 1s}.badge{font-size:11px;color:#13805e;background:#dff9ef;padding:5px 9px;border-radius:99px}.off{color:#933;background:#fee5e5}.node b{display:block;font-size:19px;margin:12px 0}.node small{display:block;overflow-wrap:anywhere;color:#607084;margin:7px 0}.node button{margin-top:12px;width:100%}button{border:1px solid #c6d1dc;background:white;color:#243344;border-radius:7px;padding:10px 13px;cursor:pointer;font-weight:600}button.primary{background:#205c87;color:white;border-color:#205c87}button:disabled{opacity:.5;cursor:default}input,select{border:1px solid #ccd6e0;border-radius:7px;padding:10px;max-width:100%;font:inherit}label{display:block;font-weight:600;margin-bottom:6px}.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.field{margin:14px 0}.log{height:330px;overflow:auto}.event{display:grid;grid-template-columns:100px 65px 95px 1fr;gap:8px;border-bottom:1px solid #edf0f3;padding:10px 0;word-break:break-word}.event span:first-child{color:#778697;font-variant-numeric:tabular-nums}.event strong{color:#205c87}.result{overflow-wrap:anywhere;color:#205c87;min-height:20px}.metrics{display:flex;gap:24px;flex-wrap:wrap;margin:16px 0}.metric{font-size:24px;font-weight:650}.metric small{display:block;color:#758497;font-size:12px;font-weight:400}.path{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.step{background:#eef3f8;padding:7px 10px;border-radius:6px;color:#52677e}.step.on{background:#dcefe8;color:#16674e}@keyframes flash{50%{box-shadow:0 0 0 4px #8bcbe0}}@media(max-width:760px){.grid{grid-template-columns:1fr}.nodes{grid-template-columns:1fr}.event{grid-template-columns:70px 45px 70px 1fr;font-size:12px}}</style></head><body><header><div><h1>Distributed Storage Lab</h1><p style="margin:4px 0">Real Go backend · TCP · SHA-256</p></div><span class="badge">LOCAL DEMO</span></header><main><section><h2>Network topology</h2><p>Three independent storage directories, connected by real TCP listeners. Pause a node to test availability.</p><div class="metrics"><div class="metric" id="live">—<small>Online nodes</small></div><div class="metric" id="copies">—<small>Stored copies</small></div><div class="metric" id="unique">—<small>Unique objects</small></div></div><svg width="100%" height="45" viewBox="0 0 900 45" preserveAspectRatio="none" aria-label="Full mesh links"><path d="M150 44 V12 H750 V44 M450 12 V44" fill="none" stroke="#94aabd" stroke-width="2" stroke-dasharray="5 4"/><circle cx="150" cy="44" r="4" fill="#205c87"/><circle cx="450" cy="44" r="4" fill="#205c87"/><circle cx="750" cy="44" r="4" fill="#205c87"/></svg><div class="nodes" id="nodes"></div><div class="path" id="steps"></div></section><div class="grid"><section><h2>Upload & replicate</h2><label for="target">Entry node</label><select id="target"><option>A</option><option>B</option><option>C</option></select><div class="field"><label for="file">File (up to 8 MiB)</label><input type="file" id="file"></div><button class="primary" id="upload">Upload file</button> <button id="sample">Try sample</button><p class="result" id="result" role="status"></p></section><section><h2>Retrieve a file</h2><label for="reader">Reader node</label><select id="reader"><option>A</option><option selected>B</option><option>C</option></select><div class="field"><label for="hash">Content address</label><input id="hash" style="width:100%" placeholder="64-character SHA-256 hash"></div><button class="primary" id="download">Retrieve & download</button><p class="result" id="retrieved" role="status"></p></section></div><section><h2>Live protocol activity</h2><p>Events recorded by the backend as operations occur. No simulated transfers.</p><div class="log" id="log" aria-live="polite"><p id="empty">Upload a file to see TCP and storage events.</p></div></section></main><script>
const el=id=>document.getElementById(id), stages=['hash','store','connect','handshake','encode','send','decode','replicate','retrieve'];let cursor=0,active={},seen=new Set(),busy=false;
function item(tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n}
function steps(){el('steps').replaceChildren(...stages.map(s=>item('span',s[0].toUpperCase()+s.slice(1),'step'+(seen.has(s)?' on':''))))}
async function call(url,options){const r=await fetch(url,options);if(!r.ok)throw Error(await r.text());return r}
async function refresh(){try{const es=await (await call('/demo/events?after='+cursor)).json();for(const e of es){cursor=e.id;active[e.node]=Date.now();seen.add(e.stage);el('empty')?.remove();const row=item('div','','event');for(const [i,v] of [e.time,'Node '+e.node,e.stage,e.detail].entries())row.append(item(i===2?'strong':'span',v));el('log').prepend(row);while(el('log').children.length>160)el('log').lastChild.remove()}steps();const nodes=await (await call('/demo/status')).json();el('live').firstChild.nodeValue=nodes.filter(n=>n.online).length+' / 3';el('copies').firstChild.nodeValue=nodes.reduce((s,n)=>s+n.files.length,0);el('unique').firstChild.nodeValue=new Set(nodes.flatMap(n=>n.files)).size;el('nodes').replaceChildren(...nodes.map(n=>{const box=item('div','','node'+(Date.now()-active[n.id]<1300?' active':''));box.append(item('span',n.online?'ONLINE':'OFFLINE','badge'+(n.online?'':' off')),item('b','Node '+n.id),item('small',n.address),item('small',n.files.length+' stored objects'));const btn=item('button',n.online?'Take offline':'Bring online');btn.onclick=async()=>{try{await call('/demo/'+n.id+'/toggle',{method:'POST'});refresh()}catch(e){el('result').textContent=e.message}};box.append(btn);return box}))}catch(e){el('result').textContent='Dashboard connection lost: '+e.message}}
async function upload(data){if(busy)return;busy=true;el('upload').disabled=el('sample').disabled=true;seen.clear();el('result').textContent='Storing and replicating…';try{const x=await(await call('/demo/'+el('target').value+'/files',{method:'POST',body:data})).json();el('hash').value=x.hash;el('result').textContent='Stored '+x.copies+' copies · '+x.hash;await refresh()}catch(e){el('result').textContent=e.message}finally{busy=false;el('upload').disabled=el('sample').disabled=false}}
el('upload').onclick=()=>{const f=el('file').files[0];if(f)upload(f);else el('result').textContent='Select a file first.'};el('sample').onclick=()=>upload(new Blob(['Distributed Storage Lab sample '+new Date().toISOString()]));el('download').onclick=async()=>{try{const h=el('hash').value.trim();if(!/^[a-f0-9]{64}$/.test(h))throw Error('Enter a valid SHA-256 address.');const r=await call('/demo/'+el('reader').value+'/files/'+h);const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=h;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('retrieved').textContent='Retrieved '+blob.size+' bytes from Node '+el('reader').value;refresh()}catch(e){el('retrieved').textContent=e.message}};steps();refresh();setInterval(refresh,1000);
</script></body></html>`
